"""Publish the compiled font's catalogue to the live HTML proof."""

import json
from pathlib import Path

from outlines import DLIGS, LIGS

ROOT = Path(__file__).resolve().parent.parent


def write_specimen_data():
    data = {
        "version": "1.0",
        "standard": list(LIGS),
        "optional": list(DLIGS),
    }
    (ROOT / "dist/specimen-data.js").write_text(
        "// Generated by extract/build.py; edit the outline catalogue.\n"
        + "const BATHYS_SPECIMEN = "
        + json.dumps(data, indent=2)
        + ";\n",
        encoding="utf-8",
        newline="\n",
    )
